using UnityEngine;using UnityEditor;using System.IO;using System.Collections.Generic;using System.Reflection;
[InitializeOnLoad]public static class RoomDoorGapCheck{
 static RoomDoorGapCheck(){EditorApplication.delayCall+=()=>{if(!File.Exists("Temp/room_door_gap_check.request")||EditorApplication.isPlaying)return;File.Delete("Temp/room_door_gap_check.request");Run();};}
 static void Run(){var report=new List<string>();Check(new[]{"Purple Room Entrance Left","Purple Room Entrance Right"},new Vector3(-15.14f,0,-.9575f),Vector3.forward,Vector3.left,2.25f,report);Check(new[]{"Bathroom Entrance Door"},new Vector3(-10.0936f,0,3.59f),Vector3.right,Vector3.forward,1.25f,report);Check(new[]{"Bedroom 01 Entrance Door"},new Vector3(1.96f,0,2.5425f),Vector3.forward,Vector3.right,1.25f,report);Check(new[]{"Bedroom 02 Entrance Door"},new Vector3(1.96f,0,-1.4575f),Vector3.forward,Vector3.right,1.25f,report);File.WriteAllLines("Temp/room_door_gap_check.txt",report);typeof(RoomDoorVerify).GetMethod("Run",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,null);}
 static void Check(string[] names,Vector3 center,Vector3 horizontal,Vector3 normal,float width,List<string> report){var objects=new List<GameObject>();var colliders=new List<MeshCollider>();bool old=Physics.queriesHitBackfaces;int gaps=0,total=0;try{Physics.queriesHitBackfaces=true;foreach(var name in names){var source=GameObject.Find(name);var o=new GameObject("Temporary mesh gap check");objects.Add(o);o.transform.SetPositionAndRotation(source.transform.position,source.transform.rotation);o.transform.localScale=source.transform.lossyScale;var col=o.AddComponent<MeshCollider>();col.sharedMesh=source.GetComponent<MeshFilter>().sharedMesh;colliders.Add(col);}Physics.SyncTransforms();for(float x=-width/2+.015f;x<width/2-.015f;x+=.01f)for(float y=.15f;y<2.05f;y+=.025f){total++;var ray=new Ray(center+horizontal*x+Vector3.up*y-normal,normal);bool hit=false;foreach(var col in colliders)if(col.Raycast(ray,out _,2)){hit=true;break;}if(!hit)gaps++;}report.Add(names[0]+": uncovered samples="+gaps+" / "+total);}finally{Physics.queriesHitBackfaces=old;foreach(var o in objects)Object.DestroyImmediate(o);}}
}
